import{_ as a,o as i,c as s,a0 as t}from"./chunks/framework.jwovEGr5.js";const p=JSON.parse('{"title":"Teaching Philosophy","description":"","frontmatter":{},"headers":[],"relativePath":"TEACHING_PHILOSOPHY.md","filePath":"TEACHING_PHILOSOPHY.md"}'),n={name:"TEACHING_PHILOSOPHY.md"};function l(o,e,r,h,c,d){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="teaching-philosophy" tabindex="-1">Teaching Philosophy <a class="header-anchor" href="#teaching-philosophy" aria-label="Permalink to &quot;Teaching Philosophy&quot;">​</a></h1><p>Language is a system, not a collection of isolated rules.</p><p>Students should understand the system rather than memorize facts.</p><hr><h2 id="core-principle-explain-the-why" tabindex="-1">Core Principle: Explain the Why <a class="header-anchor" href="#core-principle-explain-the-why" aria-label="Permalink to &quot;Core Principle: Explain the Why&quot;">​</a></h2><p>Every concept should answer these questions:</p><ul><li><strong>What?</strong> -- What is this thing?</li><li><strong>Why?</strong> -- Why does Dutch work this way?</li><li><strong>How?</strong> -- How do you use it practically?</li><li><strong>When?</strong> -- When do you use it (vs. alternatives)?</li><li><strong>Common mistakes?</strong> -- What do learners typically get wrong?</li><li><strong>Relation to English?</strong> -- How does it compare to what I already know?</li></ul><hr><h2 id="example-articles-de-het" tabindex="-1">Example: Articles (de/het) <a class="header-anchor" href="#example-articles-de-het" aria-label="Permalink to &quot;Example: Articles (de/het)&quot;">​</a></h2><h3 id="wrong-way-memorization" tabindex="-1">Wrong Way (Memorization) <a class="header-anchor" href="#wrong-way-memorization" aria-label="Permalink to &quot;Wrong Way (Memorization)&quot;">​</a></h3><p>&quot;Dutch has two articles: de and het. Memorize which words use which.&quot;</p><p><em>Result: Students memorize lists and forget them.</em></p><h3 id="right-way-system" tabindex="-1">Right Way (System) <a class="header-anchor" href="#right-way-system" aria-label="Permalink to &quot;Right Way (System)&quot;">​</a></h3><p>&quot;Dutch articles make distinctions English doesn&#39;t. Here&#39;s why:</p><ul><li>Most words use <strong>de</strong> (about 70%)</li><li>Some words use <strong>het</strong> (about 30%)</li><li>Diminutives always use <strong>het</strong></li><li>Infinitives use <strong>het</strong></li><li>Neuter words (things without gender) use <strong>het</strong></li><li>Here&#39;s a pattern you can use...</li><li>Here&#39;s what makes it hard...</li><li>Don&#39;t worry, even Dutch people look these up&quot;</li></ul><p><em>Result: Students understand the system and can make educated guesses.</em></p><hr><h2 id="progressive-learning" tabindex="-1">Progressive Learning <a class="header-anchor" href="#progressive-learning" aria-label="Permalink to &quot;Progressive Learning&quot;">​</a></h2><p>Nothing is assumed before it&#39;s explicitly taught.</p><h3 id="the-chain" tabindex="-1">The Chain <a class="header-anchor" href="#the-chain" aria-label="Permalink to &quot;The Chain&quot;">​</a></h3><ol><li><strong>A0-01:</strong> Personal pronouns (I, you, he, she, it, we, they)</li><li><strong>A0-02:</strong> Present tense of &quot;to be&quot; (am, are, is)</li><li><strong>A0-03:</strong> Articles (de/het)</li><li><strong>A0-04:</strong> Regular verbs (present tense)</li></ol><p>A lesson about articles never uses irregular verbs that haven&#39;t been taught.</p><p>A lesson about possessives never uses articles that haven&#39;t been explained.</p><h3 id="every-lesson-states-its-prerequisites" tabindex="-1">Every Lesson States Its Prerequisites <a class="header-anchor" href="#every-lesson-states-its-prerequisites" aria-label="Permalink to &quot;Every Lesson States Its Prerequisites&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Prerequisites</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Before this lesson, you should know:</span></span>
<span class="line"><span>- Personal pronouns (A0-01)</span></span>
<span class="line"><span>- Present tense of &quot;to be&quot; (A0-02)</span></span>
<span class="line"><span>- Articles (A0-03)</span></span></code></pre></div><p>Learners can check: &quot;Do I know all these? Yes? Let&#39;s go. No? Go back and review.&quot;</p><hr><h2 id="one-concept-per-lesson" tabindex="-1">One Concept Per Lesson <a class="header-anchor" href="#one-concept-per-lesson" aria-label="Permalink to &quot;One Concept Per Lesson&quot;">​</a></h2><p>A lesson introduces one major grammar concept.</p><p><strong>Not:</strong></p><ul><li>&quot;Articles and Plurals and Adjectives&quot;</li></ul><p><strong>But:</strong></p><ul><li>Lesson 1: Articles</li><li>Lesson 2: Plurals</li><li>Lesson 3: Adjectives with articles</li><li>Lesson 4: Adjectives with plurals</li></ul><h3 id="why" tabindex="-1">Why? <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why?&quot;">​</a></h3><ul><li>Clear learning objectives</li><li>Cognitive load is manageable</li><li>Easier to review</li><li>Easier to assess mastery</li><li>Easier to fix if something isn&#39;t understood</li></ul><hr><h2 id="high-frequency-first" tabindex="-1">High-Frequency First <a class="header-anchor" href="#high-frequency-first" aria-label="Permalink to &quot;High-Frequency First&quot;">​</a></h2><p>Teach the most useful words first.</p><p>The 1,000 most common Dutch words cover about 90% of everyday conversation.</p><p>We teach:</p><ol><li>Core verbs (be, have, do, go, make, etc.)</li><li>Pronouns and demonstratives</li><li>Common prepositions (in, on, at, with, to, from)</li><li>Essential adjectives (big, small, good, bad, hot, cold)</li><li>Essential nouns (person, thing, place, time)</li><li>Topic-specific vocabulary (family, food, transportation)</li></ol><p>Not:</p><ul><li>Rare technical terms</li><li>Archaic words</li><li>Obscure regional vocabulary</li><li>Things learners will never need</li></ul><hr><h2 id="active-recall-and-spaced-repetition" tabindex="-1">Active Recall and Spaced Repetition <a class="header-anchor" href="#active-recall-and-spaced-repetition" aria-label="Permalink to &quot;Active Recall and Spaced Repetition&quot;">​</a></h2><p>Every lesson includes:</p><ul><li><strong>Immediate practice</strong> -- Exercise right after learning</li><li><strong>Review within a lesson</strong> -- Recap and practice</li><li><strong>Review lessons</strong> -- Every 5 lessons, review everything</li><li><strong>Spaced reviews</strong> -- Come back to old lessons</li><li><strong>Active recall</strong> -- Prompt the learner to generate answers, not recognize them</li></ul><h3 id="why-1" tabindex="-1">Why? <a class="header-anchor" href="#why-1" aria-label="Permalink to &quot;Why?&quot;">​</a></h3><p>Memory requires effort. We optimize for retention:</p><ul><li>Most learning happens during review, not during lessons</li><li>Spaced repetition is more effective than cramming</li><li>Active recall (testing yourself) is more effective than re-reading</li><li>Retrieval strengthens memory</li></ul><hr><h2 id="reuse-and-reference" tabindex="-1">Reuse and Reference <a class="header-anchor" href="#reuse-and-reference" aria-label="Permalink to &quot;Reuse and Reference&quot;">​</a></h2><p>Grammar explanations are written once, referenced many times.</p><p>Why?</p><ul><li><strong>Consistency</strong> -- All lessons explain the same grammar the same way</li><li><strong>Maintainability</strong> -- Update grammar once, it&#39;s fixed everywhere</li><li><strong>Reduced cognitive load</strong> -- Learners see consistent patterns</li><li><strong>Efficiency</strong> -- Don&#39;t duplicate work</li></ul><hr><h2 id="mistakes-are-data" tabindex="-1">Mistakes Are Data <a class="header-anchor" href="#mistakes-are-data" aria-label="Permalink to &quot;Mistakes Are Data&quot;">​</a></h2><p>Common mistakes should be collected, analyzed, and addressed.</p><p>Every grammar explanation includes a &quot;Common Mistakes&quot; section.</p><p>Why?</p><ul><li>Learners make predictable mistakes</li><li>Addressing them prevents them</li><li>It shows the learner we understand how language learning works</li><li>It builds confidence (&quot;I&#39;m not stupid, this is just hard&quot;)</li></ul><hr><h2 id="comparison-to-english" tabindex="-1">Comparison to English <a class="header-anchor" href="#comparison-to-english" aria-label="Permalink to &quot;Comparison to English&quot;">​</a></h2><p>Learners are native English speakers. Use that.</p><p><strong>English:</strong> &quot;I go, you go, he goes, we go, they go&quot;</p><p><strong>Dutch:</strong> &quot;ik ga, jij gaat, hij gaat, wij gaan, zij gaan&quot;</p><p><strong>Insight:</strong> Dutch conjugates the same way as English, but with different sound patterns. The system is the same.</p><p>Why?</p><ul><li>Reduces cognitive load (learners can build on what they know)</li><li>Shows that Dutch isn&#39;t arbitrary</li><li>Builds confidence</li><li>Helps learners understand <em>why</em> Dutch works</li></ul><hr><h2 id="reduce-cognitive-load" tabindex="-1">Reduce Cognitive Load <a class="header-anchor" href="#reduce-cognitive-load" aria-label="Permalink to &quot;Reduce Cognitive Load&quot;">​</a></h2><p>Every explanation should be as simple as possible.</p><h3 id="simple-language" tabindex="-1">Simple Language <a class="header-anchor" href="#simple-language" aria-label="Permalink to &quot;Simple Language&quot;">​</a></h3><ul><li>Use short sentences</li><li>Use common words</li><li>Avoid jargon (or explain it first)</li><li>Use examples generously</li><li>Use analogies to things learners know</li></ul><h3 id="scaffolding" tabindex="-1">Scaffolding <a class="header-anchor" href="#scaffolding" aria-label="Permalink to &quot;Scaffolding&quot;">​</a></h3><ul><li>Start with simple examples</li><li>Gradually add complexity</li><li>Show the pattern before exceptions</li><li>Introduce exceptions carefully</li></ul><h3 id="not-overwhelming" tabindex="-1">Not Overwhelming <a class="header-anchor" href="#not-overwhelming" aria-label="Permalink to &quot;Not Overwhelming&quot;">​</a></h3><ul><li>One concept per lesson</li><li>20-35 new vocabulary items per lesson</li><li>Exercises should feel manageable, not impossible</li><li>Success builds confidence</li></ul><hr><h2 id="learning-goals" tabindex="-1">Learning Goals <a class="header-anchor" href="#learning-goals" aria-label="Permalink to &quot;Learning Goals&quot;">​</a></h2><p>By the end of each level, the learner should be able to:</p><p><strong>A0:</strong></p><ul><li>Read Dutch with confidence</li><li>Introduce themselves</li><li>Ask and answer basic questions</li><li>Build simple sentences</li><li>Understand core grammar concepts</li></ul><p><strong>A1:</strong></p><ul><li>Conduct basic conversations</li><li>Discuss everyday topics (family, food, home)</li><li>Understand and respond to simple requests</li><li>Read simple texts</li><li>Write simple messages</li></ul><p><strong>A2:</strong></p><ul><li>Handle practical situations (shopping, healthcare, work)</li><li>Discuss opinions and experiences</li><li>Read and understand simple news</li><li>Write emails and longer messages</li><li>Understand conversations at normal speed</li></ul><p><strong>B1:</strong></p><ul><li>Discuss complex topics and opinions</li><li>Understand most news and entertainment</li><li>Write formal and informal communication</li><li>Participate in professional discussions</li><li>Demonstrate cultural understanding</li></ul><hr><h2 id="assessment" tabindex="-1">Assessment <a class="header-anchor" href="#assessment" aria-label="Permalink to &quot;Assessment&quot;">​</a></h2><p>Assessment should measure understanding, not memorization.</p><p><strong>Not:</strong> &quot;Conjugate the verb regnen (to rain) in all tenses&quot;</p><p><strong>But:</strong> &quot;Write 3 sentences about what the weather was like yesterday&quot;</p><p>Why?</p><ul><li>Shows real-world language ability</li><li>Measures understanding, not recall</li><li>More useful for learning</li><li>More engaging for learners</li></ul>`,96)])])}const g=a(n,[["render",l]]);export{p as __pageData,g as default};
